css:
body {
    font-family: Arial, Helvetica, sans-serif;
    text-align: center;
    background-color: #f4f4f4; /* Subtle background */
    display: flex;
    flex-direction: column;
}

h1 {
    font-size: 32px;
    margin-bottom: 5px;
    margin-top: 0;
}

#errors {
    font-size: 20px;
    font-weight: bold;
    color: coral;
    margin-top: 10px;
}

#board {
    width: 450px;
    height: 450px;
    margin: 20px auto;
    display: grid;
    grid-template-columns: repeat(9, 1fr);
    grid-template-rows: repeat(9, 1fr);
    gap: 2px;
}

.tile {
    width: 48px;
    height: 48px;
    border: 1px solid lightgray;
    font-size: 20px;
    font-weight: bold;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: row;
    cursor: pointer;
    transition: background 0.2s ease-in-out;
}

/* Add hover effect for better UX */
.tile:hover {
    background: #e0e0e0;
}

.number {
    width: 48px;
    height: 48px;
    border: 2px solid black;
    margin: 5px;
    font-size: 20px;
    font-weight: bold;
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    background: white;
    transition: background 0.2s ease-in-out;
}

/* Highlight selected number */
.number-selected {
    background-color: gray;
    color: white;
}

.tile-start {
    background-color: whitesmoke;
    font-weight: bold;
}

/* Thicker lines for 3x3 subgrids */
.horizontal-line {
    border-bottom: 2px solid black;
}

.vertical-line {
    border-right: 2px solid black;
}

#digits {
    display: flex;
}

